/// How much of a `ceiling`-byte space to back at birth.
/// 
/// 8 MiB, or the whole ceiling when that is smaller. Large enough that
/// making a collector -- a 2 MiB nursery's two halves, the first 1 MiB
/// old chunk and the never-used page at address zero -- does not grow it.
pub fn space_initial(ceiling: Addr) -> Addr {
    if 8388608 < ceiling {
        return 8388608;
    }
    return ceiling;
}
/// How much to back once something needs bytes up to `need`.
/// 
/// `committed` when it already covers `need`; otherwise double it, or
/// `need` itself if doubling is not enough, and never past `ceiling`.
pub fn space_grow_to(committed: Addr, need: Addr, ceiling: Addr) -> Addr {
    if committed < need {
        let doubled: Addr = committed * 2;
        if doubled < need {
            return need;
        }
        if ceiling < doubled {
            return ceiling;
        }
        return doubled;
    }
    return committed;
}
